<?php
namespace ZinCelestial\Platform\Admin;use ZinCelestial\Platform\Security\SecurityService;defined('ABSPATH')||exit;
final class SecurityPage{public function register():void{add_action('admin_menu',array($this,'site'));add_action('network_admin_menu',array($this,'network'));}public function site():void{add_submenu_page('zcp-control-center','Security Center','Security','manage_options','zcp-security',array($this,'render'));}public function network():void{if(is_multisite())add_submenu_page('zcp-network','Network Security','Security','manage_network_options','zcp-network-security',array($this,'render'));}public function render():void{$cap=is_network_admin()?'manage_network_options':'manage_options';if(!current_user_can($cap))wp_die(esc_html__('Insufficient permissions.','zincelestial-platform'));$s=new SecurityService();$r=$s->report();echo '<div class="wrap"><h1>'.esc_html__('Security Center','zincelestial-platform').'</h1><p><strong>'.esc_html__('Advisory score:','zincelestial-platform').' '.esc_html((string)$s->score($r)).'/100</strong></p><p>'.esc_html__('Read-only posture report. No security setting is changed.','zincelestial-platform').'</p><textarea class="large-text code" rows="28" readonly>'.esc_textarea(wp_json_encode($r,JSON_PRETTY_PRINT)).'</textarea></div>';}}
